def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    pluses=[]
    for r in range(1,h-1):
        for c in range(1,w-1):
            v=g[r][c]
            if g[r-1][c]==3 and g[r+1][c]==3 and g[r][c-1]==3 and g[r][c+1]==3:
                pluses.append((r,c, 0 if v==0 else v))
    def beam(r,c,dr,dc,col):
        first=True
        while True:
            r+=dr; c+=dc
            if not (0<=r<h and 0<=c<w): return
            v=g[r][c]
            if v==3:
                if first: first=False; continue
                return
            if v not in (0,3): return
            out[r][c]=col
    for r,c,col in pluses:
        beam(r,c,0,-1,col); beam(r,c,0,1,col)
    for r,c,col in pluses:
        beam(r,c,-1,0,col); beam(r,c,1,0,col)
    return out
